async function dl(e){
  if (e && e.preventDefault) e.preventDefault();
  const bin = atob(RESUME_B64), u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  const blob = new Blob([u8], { type: "application/pdf" });
  try { const d = window.claude && await window.claude.use("downloads"); if (d) { await d.save({ filename: DATA.resumeFile, data: blob }); return; } }
  catch (err) { if (err && err.code === "declined") return; }
  const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = DATA.resumeFile; a.click();
}

