function useActive() {
  const [a, setA] = useState("top");
  useEffect(() => {
    const io = new IntersectionObserver(es => es.forEach(e => e.isIntersecting && setA(e.target.id)), { rootMargin: "-40% 0px -55% 0px" });
    IDS.forEach(id => { const el = document.getElementById(id); el && io.observe(el); });
    return () => io.disconnect();
  }, []);
  return a;
}

function Reveal({ children, className = "" }) {
  const ref = useRef(null); const [on, setOn] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el || !("IntersectionObserver" in window)) return setOn(true);
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setOn(true); io.disconnect(); } }, { threshold: .1 });
    io.observe(el); return () => io.disconnect();
  }, []);
  return html`<div ref=${ref} className=${"reveal " + (on ? "in " : "") + className}>${children}</div>`;
}
function Count({ to, suffix = "", dec = 0 }) {
  const ref = useRef(null); const [v, setV] = useState(0);
  useEffect(() => {
    const io = new IntersectionObserver(([e]) => {
      if (!e.isIntersecting) return; io.disconnect(); const t0 = performance.now();
      const f = t => { const p = Math.min(1, (t - t0) / 1400); setV(to * (1 - Math.pow(1 - p, 3))); if (p < 1) requestAnimationFrame(f); };
      requestAnimationFrame(f);
    }, { threshold: .5 });
    io.observe(ref.current); return () => io.disconnect();
  }, []);
  return html`<span ref=${ref}>${v.toFixed(dec)}${suffix}</span>`;
}
