function Tilt({ children, className = "", onClick, style }) {
  const ref = useRef(null);
  const move = e => { const r = ref.current.getBoundingClientRect(); const x = (e.clientX - r.left) / r.width - .5, y = (e.clientY - r.top) / r.height - .5; ref.current.style.transform = `perspective(900px) rotateX(${(-y * 7).toFixed(2)}deg) rotateY(${(x * 9).toFixed(2)}deg)`; };
  return html`<div ref=${ref} onMouseMove=${move} onMouseLeave=${() => { ref.current.style.transform = ""; }} onClick=${onClick} style=${style} className=${"tilt " + className}>${children}</div>`;
}

function Cursor() {
  const d = useRef(null), r = useRef(null);
  useEffect(() => {
    if (window.matchMedia("(pointer: coarse)").matches) return;
    let x = -50, y = -50, rx = -50, ry = -50, raf;
    const mv = e => { x = e.clientX; y = e.clientY; d.current.style.transform = `translate(${x}px,${y}px)`; };
    const loop = () => { rx += (x - rx) * .18; ry += (y - ry) * .18; r.current.style.transform = `translate(${rx}px,${ry}px)`; raf = requestAnimationFrame(loop); };
    window.addEventListener("mousemove", mv); loop();
    return () => { window.removeEventListener("mousemove", mv); cancelAnimationFrame(raf); };
  }, []);
  return html`<div><div ref=${r} className="cur ring" aria-hidden="true"></div><div ref=${d} className="cur dot" aria-hidden="true"></div></div>`;
}

function Scene3D() {
  const ref = useRef(null);
  useEffect(() => {
    const T = window.THREE; if (!T || !ref.current) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let r; try { r = new T.WebGLRenderer({ canvas: ref.current, alpha: true, antialias: true }); } catch (e) { return; }
    r.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    const scene = new T.Scene(), cam = new T.PerspectiveCamera(50, 1, .1, 100); cam.position.z = 8;
    const g = new T.Group(); scene.add(g);
    const rm = new T.MeshBasicMaterial({ color: 0xf0283c, transparent: true, opacity: .75 });
    const rings = [0, 1, 2].map(i => { const m = new T.Mesh(new T.TorusGeometry(2.5 + i * .35, .006, 8, 200), rm); m.scale.y = .42 + i * .12; m.rotation.z = i * 1.05 - .5; m.rotation.x = .9 - i * .35; g.add(m); return m; });
    const oct = new T.Mesh(new T.OctahedronGeometry(.16), new T.MeshBasicMaterial({ color: 0xf0283c, wireframe: true })); oct.position.set(-2.2, -.6, .5); g.add(oct);
    const box = new T.Mesh(new T.BoxGeometry(.18, .18, .18), new T.MeshBasicMaterial({ color: 0xff5a66 })); box.position.set(2.6, .9, 0); g.add(box);
    const ico = new T.Mesh(new T.IcosahedronGeometry(.9, 1), new T.MeshBasicMaterial({ color: 0xf0283c, wireframe: true, transparent: true, opacity: .22 })); g.add(ico);
    const n = 260, pos = new Float32Array(n * 3);
    for (let i = 0; i < n * 3; i++) pos[i] = (Math.random() - .5) * 24;
    const pg = new T.BufferGeometry(); pg.setAttribute("position", new T.BufferAttribute(pos, 3));
    const pts = new T.Points(pg, new T.PointsMaterial({ color: 0xf0283c, size: .06, transparent: true, opacity: .8 })); scene.add(pts);
    let mx = 0, my = 0, sy = 0, raf;
    const size = () => { r.setSize(window.innerWidth, window.innerHeight, false); cam.aspect = window.innerWidth / window.innerHeight; cam.updateProjectionMatrix(); };
    const mm = e => { mx = e.clientX / window.innerWidth - .5; my = e.clientY / window.innerHeight - .5; };
    const sc = () => { const h = document.documentElement; sy = h.scrollTop / Math.max(1, h.scrollHeight - h.clientHeight); };
    size(); sc();
    window.addEventListener("resize", size); window.addEventListener("mousemove", mm); window.addEventListener("scroll", sc, { passive: true });
    const tick = t => {
      const time = t / 1000, mobile = window.innerWidth < 768;
      const tx = mobile ? 0 : 3.1 - sy * 7 + Math.sin(sy * 14) * .8;
      g.position.x += (Math.max(-3.4, tx) - g.position.x) * .05; g.position.y += ((mobile ? 2 : .4) + Math.sin(sy * 9) * 1.1 - g.position.y) * .05;
      g.scale.setScalar(mobile ? .55 : 1);
      rings.forEach((m, i) => { m.rotation.y = time * (.12 + i * .05) + mx * .6; m.rotation.z += .0015 * (i + 1); });
      oct.rotation.x = time; oct.rotation.y = time * .7; box.rotation.y = time * .9; box.rotation.x = time * .5; ico.rotation.y = -time * .2;
      pts.rotation.y = time * .015 + sy * 1.5; pts.position.y = sy * 4;
      cam.position.x += (mx * .8 - cam.position.x) * .05; cam.position.y += (-my * .5 - cam.position.y) * .05; cam.lookAt(0, 0, 0);
      r.render(scene, cam); if (!reduce) raf = requestAnimationFrame(tick);
    };
    tick(0);
    return () => { cancelAnimationFrame(raf); window.removeEventListener("resize", size); window.removeEventListener("mousemove", mm); window.removeEventListener("scroll", sc); r.dispose(); };
  }, []);
  return html`<canvas ref=${ref} aria-hidden="true" style=${{ position: "fixed", inset: 0, width: "100%", height: "100%", zIndex: 0, pointerEvents: "none" }}></canvas>`;
}

