function Typing({ words }) {
  const [i, setI] = useState(0), [t, setT] = useState(""), [del, setDel] = useState(false);
  useEffect(() => {
    const w = words[i]; let d = del ? 35 : 85; if (!del && t === w) d = 1500; if (del && t === "") d = 300;
    const id = setTimeout(() => {
      if (!del && t === w) setDel(true); else if (del && t === "") { setDel(false); setI((i + 1) % words.length); } else setT(w.slice(0, t.length + (del ? -1 : 1)));
    }, d); return () => clearTimeout(id);
  }, [t, del, i]);
  return html`<span style=${{ color: "#fff" }}>${t}</span><span className="caret"></span>`;
}

