function Meter({ n, v }) {
  const ref = useRef(null); const [on, setOn] = useState(false);
  useEffect(() => { const io = new IntersectionObserver(([e]) => e.isIntersecting && setOn(true), { threshold: .4 }); io.observe(ref.current); return () => io.disconnect(); }, []);
  return html`<div ref=${ref} className="mb-3"><div className="flex justify-between text-xs mb-1"><span>${n}</span><span className="mono" style=${MUTE}>${v}%</span></div><div className="h-1" style=${{ background: "var(--line)" }}><div className="h-full bar" style=${{ background: "var(--red)", width: "100%", transform: on ? `scaleX(${v / 100})` : "scaleX(0)" }}></div></div></div>`;
}

